-- 기술 주제 목록(고정 77개). 프로젝트 상세 "기술 이야기" 탭 이름, BE, FE, AN 탭 나누기(side), 주제 검색(synonyms)에 쓴다.
-- 목록은 바뀔 일이 드물어 적재기가 아니라 이 마이그레이션으로 한 번 넣는다. 바꿀 때는 새 마이그레이션을 쓴다.
-- 데이터 파이프라인 config/topics.json(LLM 이 고르는 목록)과 같아야 한다(결정 기록 66, 67번).
CREATE TABLE resource_topic_catalog (
    id         VARCHAR(40)  PRIMARY KEY,
    name       VARCHAR(100) NOT NULL,
    side       VARCHAR(10)  NOT NULL CHECK (side IN ('backend', 'frontend', 'mobile', 'common')),
    category   VARCHAR(40)  NOT NULL,
    synonyms   TEXT[]       NOT NULL DEFAULT '{}',
    sort_order SMALLINT     NOT NULL
);


-- 문서의 주제는 목록에 있는 id 만 들어간다
ALTER TABLE resource_documents
    ADD CONSTRAINT resource_documents_topic_fkey FOREIGN KEY (topic) REFERENCES resource_topic_catalog (id);
